changeSet.sql:
DO $$
DECLARE n int;
BEGIN
  LOOP
    UPDATE job_offer
       SET description_oid = description::oid
     WHERE id IN (
           SELECT id FROM job_offer
            WHERE description ~ '^[0-9]+$'
              AND description_oid IS NULL
            LIMIT 5000
     );
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    COMMIT;
  END LOOP;
END $$;

DO $$
DECLARE n int;
BEGIN
  LOOP
    UPDATE job_offer
       SET description = convert_from(lo_get(description_oid), 'UTF8')
     WHERE id IN (
           SELECT id FROM job_offer
            WHERE description_oid IS NOT NULL
              AND description ~ '^[0-9]+$'
            LIMIT 5000
     );
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    COMMIT;
  END LOOP;
END $$;

DO $$
DECLARE n int;
BEGIN
  LOOP
    WITH lot AS (
      SELECT id, description_oid FROM job_offer
       WHERE description_oid IS NOT NULL LIMIT 5000
    ), del AS (
      SELECT lo_unlink(description_oid) FROM lot
       WHERE description_oid IN (SELECT oid FROM pg_largeobject_metadata)
    )
    UPDATE job_offer SET description_oid = NULL WHERE id IN (SELECT id FROM lot);
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    COMMIT;
  END LOOP;
END $$;
